CREATE TABLE public.adr_cases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),org_id uuid NOT NULL REFERENCES public.organisations(id) ON DELETE CASCADE,complaint_id uuid NOT NULL UNIQUE REFERENCES public.complaints(id) ON DELETE CASCADE,adr_body_name text NOT NULL,adr_reference text,escalated_on date NOT NULL,firm_notified_on date,firm_response_due date,firm_response_sent_on date,decision text NOT NULL DEFAULT 'pending' CHECK(decision IN ('pending','upheld_firm','overturned','partially_overturned','settled','withdrawn')),decision_on date,award_amount numeric,award_currency text,notes text CHECK(length(notes)<=2000),created_by uuid,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE ON public.adr_cases TO authenticated;
GRANT ALL ON public.adr_cases TO service_role;
ALTER TABLE public.adr_cases ENABLE ROW LEVEL SECURITY;
CREATE POLICY adr_read ON public.adr_cases FOR SELECT TO authenticated USING(public.is_org_member(org_id));
CREATE POLICY adr_insert ON public.adr_cases FOR INSERT TO authenticated WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=adr_cases.org_id AND c.assigned_to=auth.uid())));
CREATE POLICY adr_update ON public.adr_cases FOR UPDATE TO authenticated USING(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=adr_cases.org_id AND c.assigned_to=auth.uid()))) WITH CHECK(public.has_org_role(org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(org_id,ARRAY['agent']::public.app_role[]) AND EXISTS(SELECT 1 FROM public.complaints c WHERE c.id=complaint_id AND c.org_id=adr_cases.org_id AND c.assigned_to=auth.uid())));
CREATE FUNCTION public.adr_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE c public.complaints; codes text[]:=ARRAY['EUR','GBP','PLN','CZK','HUF','RON','SEK','DKK','NOK','CHF','BGN','ISK','USD']; today date:=(now() AT TIME ZONE 'UTC')::date; BEGIN SELECT * INTO c FROM public.complaints WHERE id=NEW.complaint_id AND org_id=NEW.org_id FOR UPDATE; IF c.id IS NULL OR c.legal_hold OR c.privacy_processing OR c.anonymised_at IS NOT NULL THEN RAISE EXCEPTION 'This complaint is locked'; END IF;
IF TG_OP='UPDATE' THEN IF NEW.id<>OLD.id OR NEW.org_id<>OLD.org_id OR NEW.complaint_id<>OLD.complaint_id THEN RAISE EXCEPTION 'ADR identity cannot change'; END IF; NEW.created_by:=OLD.created_by; NEW.created_at:=OLD.created_at; NEW.adr_body_name:=OLD.adr_body_name; IF c.status<>'escalated_to_adr' THEN RAISE EXCEPTION 'ADR record is read-only after closure'; END IF;
ELSE IF c.status NOT IN ('final_response_sent','closed') THEN RAISE EXCEPTION 'ADR escalation requires a final response or closed complaint'; END IF; SELECT adr_name INTO NEW.adr_body_name FROM public.org_countries WHERE org_id=c.org_id AND country_code=c.country_code; NEW.created_by:=auth.uid(); NEW.created_at:=now(); END IF;
IF coalesce(length(trim(NEW.adr_body_name)),0)=0 THEN RAISE EXCEPTION 'Configure an ADR body for this country'; END IF;
IF NEW.escalated_on<(c.received_at AT TIME ZONE 'UTC')::date OR NEW.escalated_on>today THEN RAISE EXCEPTION 'Escalation date must be between receipt and today'; END IF;
IF NEW.decision<>'pending' AND NEW.decision_on IS NULL THEN RAISE EXCEPTION 'ADR decision date is required'; END IF;
IF NEW.decision_on IS NOT NULL AND (NEW.decision_on<NEW.escalated_on OR NEW.decision_on>today) THEN RAISE EXCEPTION 'Invalid decision date'; END IF;
IF NEW.decision='pending' AND NEW.decision_on IS NOT NULL THEN RAISE EXCEPTION 'Pending ADR has no decision date'; END IF;
IF NEW.firm_notified_on IS NOT NULL AND (NEW.firm_notified_on<NEW.escalated_on OR NEW.firm_notified_on>today) THEN RAISE EXCEPTION 'Invalid notification date'; END IF;
IF NEW.firm_response_due IS NOT NULL AND NEW.firm_response_due<NEW.escalated_on THEN RAISE EXCEPTION 'Invalid response due date'; END IF;
IF NEW.firm_response_sent_on IS NOT NULL AND (NEW.firm_response_sent_on<NEW.escalated_on OR NEW.firm_response_sent_on>today) THEN RAISE EXCEPTION 'Invalid response sent date'; END IF;
IF (NEW.award_amount IS NULL)<>(NEW.award_currency IS NULL) OR NEW.award_amount<0 OR NEW.award_amount::text IN ('NaN','Infinity','-Infinity') OR (NEW.award_currency IS NOT NULL AND NOT NEW.award_currency=ANY(codes)) THEN RAISE EXCEPTION 'Invalid award amount or currency'; END IF; NEW.updated_at:=now(); RETURN NEW; END $$;
CREATE TRIGGER adr_guard BEFORE INSERT OR UPDATE ON public.adr_cases FOR EACH ROW EXECUTE FUNCTION public.adr_guard();
CREATE TRIGGER privacy_adr_guard BEFORE INSERT OR UPDATE ON public.adr_cases FOR EACH ROW EXECUTE FUNCTION public.privacy_child_guard();
CREATE TRIGGER audit_adr AFTER INSERT OR UPDATE OR DELETE ON public.adr_cases FOR EACH ROW EXECUTE FUNCTION public.audit_capture();
CREATE FUNCTION public.adr_events() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN UPDATE public.complaints SET status='escalated_to_adr' WHERE id=NEW.complaint_id AND org_id=NEW.org_id; INSERT INTO public.complaint_events(org_id,complaint_id,actor,kind,detail) VALUES(NEW.org_id,NEW.complaint_id,auth.uid(),'adr_escalated',jsonb_build_object('text','Escalated to ADR (ref '||coalesce(NEW.adr_reference,'not recorded')||')')); END IF; IF NEW.decision<>'pending' AND (TG_OP='INSERT' OR NEW.decision IS DISTINCT FROM OLD.decision OR NEW.decision_on IS DISTINCT FROM OLD.decision_on) THEN INSERT INTO public.complaint_events(org_id,complaint_id,actor,kind,detail) VALUES(NEW.org_id,NEW.complaint_id,auth.uid(),'adr_decision',jsonb_build_object('text','ADR decision: '||replace(NEW.decision,'_',' '))); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.adr_events() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER adr_events AFTER INSERT OR UPDATE ON public.adr_cases FOR EACH ROW EXECUTE FUNCTION public.adr_events();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.complaints_status_guard()'::regprocedure) INTO def; def:=replace(def,'OLD.status IN (''closed'',''escalated_to_adr'')','OLD.status=''closed'''); def:=replace(def,'IF OLD.status<>''final_response_sent'' THEN','IF OLD.status<>''final_response_sent'' AND NOT (OLD.status=''escalated_to_adr'' AND EXISTS(SELECT 1 FROM public.adr_cases a WHERE a.complaint_id=NEW.id AND a.org_id=NEW.org_id AND a.decision<>''pending'')) THEN'); EXECUTE def; END $$;
CREATE FUNCTION public.adr_status_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.status IS DISTINCT FROM OLD.status AND (OLD.status='escalated_to_adr' OR NEW.status='escalated_to_adr') THEN IF OLD.legal_hold OR OLD.privacy_processing OR OLD.anonymised_at IS NOT NULL THEN RAISE EXCEPTION 'This complaint is locked'; END IF; IF auth.uid() IS NOT NULL AND NOT (public.has_org_role(OLD.org_id,ARRAY['org_admin','complaints_manager']::public.app_role[]) OR (public.has_org_role(OLD.org_id,ARRAY['agent']::public.app_role[]) AND OLD.assigned_to=auth.uid())) THEN RAISE EXCEPTION 'You cannot manage ADR'; END IF; IF NEW.status='escalated_to_adr' AND NOT EXISTS(SELECT 1 FROM public.adr_cases WHERE complaint_id=NEW.id AND org_id=NEW.org_id) THEN RAISE EXCEPTION 'Record ADR escalation first'; END IF; IF NEW.status='closed' AND NOT EXISTS(SELECT 1 FROM public.adr_cases WHERE complaint_id=NEW.id AND org_id=NEW.org_id AND decision<>'pending') THEN RAISE EXCEPTION 'Record the ADR decision before closing'; END IF; END IF; RETURN NEW; END $$;
CREATE TRIGGER adr_status_guard BEFORE UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.adr_status_guard();
CREATE FUNCTION public.adr_anonymise() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF OLD.anonymised_at IS NULL AND NEW.anonymised_at IS NOT NULL THEN DELETE FROM public.adr_cases WHERE complaint_id=NEW.id AND org_id=NEW.org_id; UPDATE public.complaint_events SET detail='{}'::jsonb WHERE complaint_id=NEW.id AND org_id=NEW.org_id AND kind IN ('adr_escalated','adr_decision'); END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.adr_anonymise() FROM PUBLIC,anon,authenticated;
CREATE TRIGGER adr_anonymise AFTER UPDATE ON public.complaints FOR EACH ROW EXECUTE FUNCTION public.adr_anonymise();
DO $$ DECLARE def text; BEGIN SELECT pg_get_functiondef('public.audit_minimise(text,jsonb)'::regprocedure) INTO def; def:=replace(def,'ELSE _row END','WHEN _table=''adr_cases'' THEN _row-ARRAY[''notes'',''adr_reference''] ELSE _row END'); EXECUTE def; END $$;
DO $$ DECLARE def text; BEGIN SELECT rtrim(pg_get_viewdef('public.complaint_queue'::regclass,true),E';\n ') INTO def; EXECUTE 'CREATE OR REPLACE VIEW public.complaint_queue WITH (security_invoker=true) AS SELECT q.*,a.escalated_on AS adr_escalated_on,a.decision AS adr_decision,a.decision_on AS adr_decision_on,a.award_amount AS adr_award_amount,a.award_currency AS adr_award_currency FROM ('||def||') q LEFT JOIN public.adr_cases a ON a.complaint_id=q.id AND a.org_id=q.org_id'; END $$;
GRANT SELECT ON public.complaint_queue TO authenticated;
COMMENT ON TABLE public.adr_cases IS 'One ADR working record per complaint; pending decision is active. Authorised anonymisation removes working records; immutable audit history is retained.';